example.code:
from dataclasses import dataclass
from typing import Optional
import asyncio

from telegram import Bot
from telegram.error import RetryAfter, BadRequest, TelegramError

from api.config import get_config
from api.logging import get_logger

logger = get_logger(__name__)

@dataclass
class DeliveryResult:
    """Result of message delivery attempt."""
    success: bool
    message_id: Optional[int]
    error: Optional[str]

async def deliver_message(
    user_id: str,
    message: str,
    parse_mode: str = "HTML",
    max_retries: int = 3
) -> DeliveryResult:
    """
    Deliver proactive message to user via Telegram.

    Args:
        user_id: User identifier (Telegram chat_id as string)
        message: Message text to send
        parse_mode: Telegram parse mode (HTML or Markdown)
        max_retries: Maximum retry attempts for rate limits

    Returns:
        DeliveryResult with success status and message_id
    """
    # Input validation
    if not user_id or not user_id.strip():
        error_msg = "user_id cannot be empty"
        logger.error(error_msg, extra={"event": "delivery_validation_failed"})
        return DeliveryResult(success=False, message_id=None, error=error_msg)

    if not message or not message.strip():
        error_msg = "message cannot be empty"
        logger.error(error_msg, extra={"user_id": user_id, "event": "delivery_validation_failed"})
        return DeliveryResult(success=False, message_id=None, error=error_msg)

    try:
        # Convert user_id (string) to chat_id (int)
        try:
            chat_id = int(user_id)
        except ValueError:
            error_msg = f"Invalid user_id format: {user_id}"
            logger.error(error_msg, extra={"user_id": user_id, "event": "delivery_validation_failed"})
            return DeliveryResult(success=False, message_id=None, error=error_msg)

        # Initialize Bot
        config = get_config()
        bot_token = config.get("TELEGRAM_BOT_TOKEN")
        bot = Bot(token=bot_token)

        # Retry loop for rate limiting
        for attempt in range(1, max_retries + 1):
            try:
                logger.info(
                    "Attempting to deliver message",
                    extra={
                        "user_id": user_id,
                        "chat_id": chat_id,
                        "message_length": len(message),
                        "attempt": attempt,
                        "event": "delivery_attempt"
                    }
                )

                # Send message via Telegram API
                message_obj = await bot.send_message(
                    chat_id=chat_id,
                    text=message,
                    parse_mode=parse_mode
                )

                logger.info(
                    "Message delivered successfully",
                    extra={
                        "user_id": user_id,
                        "chat_id": chat_id,
                        "message_id": message_obj.message_id,
                        "attempt": attempt,
                        "event": "delivery_success"
                    }
                )

                return DeliveryResult(
                    success=True,
                    message_id=message_obj.message_id,
                    error=None
                )

            except RetryAfter as e:
                wait_time = e.retry_after
                logger.warning(
                    f"Rate limited by Telegram, retry_after={wait_time}s",
                    extra={
                        "user_id": user_id,
                        "chat_id": chat_id,
                        "retry_after": wait_time,
                        "attempt": attempt,
                        "max_retries": max_retries,
                        "event": "delivery_rate_limited"
                    }
                )

                if attempt < max_retries:
                    await asyncio.sleep(wait_time)
                else:
                    error_msg = f"Rate limited after {max_retries} retries"
                    logger.error(
                        error_msg,
                        extra={
                            "user_id": user_id,
                            "chat_id": chat_id,
                            "event": "delivery_failed_rate_limit"
                        }
                    )
                    return DeliveryResult(success=False, message_id=None, error=error_msg)

    except BadRequest as e:
        error_msg = f"Invalid Telegram request: {str(e)}"
        logger.error(
            error_msg,
            extra={
                "user_id": user_id,
                "error": str(e),
                "error_type": "BadRequest",
                "event": "delivery_failed_bad_request"
            },
            exc_info=True
        )
        return DeliveryResult(success=False, message_id=None, error=error_msg)

    except TelegramError as e:
        error_msg = f"Telegram API error: {str(e)}"
        logger.error(
            error_msg,
            extra={
                "user_id": user_id,
                "error": str(e),
                "error_type": type(e).__name__,
                "event": "delivery_failed_telegram_error"
            },
            exc_info=True
        )
        return DeliveryResult(success=False, message_id=None, error=error_msg)

    except Exception as e:
        error_msg = f"Unexpected error during delivery: {str(e)}"
        logger.error(
            error_msg,
            extra={
                "user_id": user_id,
                "error": str(e),
                "error_type": type(e).__name__,
                "event": "delivery_failed_unexpected"
            },
            exc_info=True
        )
        return DeliveryResult(success=False, message_id=None, error=error_msg)

